/**
 * Repair Detail Page
 *
 * Shows full repair information including customer, bicycle, line items, work logs (timers),
 * and notes. Technicians can start/stop manual work timers to track actual time spent on repairs.
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import {
  ArrowLeft,
  Play,
  Square,
  Clock,
  FileText,
  StickyNote,
  User,
  ChevronDown,
  ChevronUp,
  Pencil,
  Check,
  X,
  Trash2,
  Search,
  Plus,
  Calendar,
} from 'lucide-react'
import { Textarea } from '@/components/ui/textarea.js'
import {
  STATUS_COLORS,
  type RepairStatus,
} from '../types.js'
import toast from 'react-hot-toast'

// ---------------------------------------------------------------------------
// Types — match API response shapes
// ---------------------------------------------------------------------------

/** Worker option for the assignment dropdown */
interface WorkerOption {
  id: string
  name: string
  role: 'mechanic' | 'manager'
}

/** Part catalog item from parts search */
interface PartCatalogItem {
  id: string
  barcode: string
  name: string
  priceNet: number
  quantityOnHand: number
}

/** Labor service option for the labor tab */
interface LaborServiceOption {
  id: string
  name: string
  description: string | null
  billingType: 'hourly' | 'fixed'
  defaultRate: number
}

interface RepairHeader {
  id: string
  bicycleId: string
  assignedTo: string | null
  status: RepairStatus
  customerNotes: string | null
  internalNotes: string | null
  holdReason: 'waiting_parts' | 'awaiting_customer_approval' | 'other' | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
}

interface CustomerInfo {
  id: string
  firstName: string | null
  lastName: string | null
  companyName: string | null
  phone: string | null
  email: string | null
}

interface BicycleInfo {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

interface LineItem {
  id: string
  repairId: string
  lineType: 'part' | 'labor'
  partId: string | null
  laborServiceId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
  minutesWorked: number | null
  hourlyRateSnapshot: number | null
  createdAt: number
}

interface WorkLog {
  id: string
  repairId: string
  userId: string
  startedAt: number | null
  endedAt: number | null
  durationMs?: number
}

interface RepairDetailResponse {
  repair: RepairHeader
  customer?: CustomerInfo
  bicycle: BicycleInfo
  lineItems: LineItem[]
  workLogs: WorkLog[]
}

// ---------------------------------------------------------------------------
// API functions
// ---------------------------------------------------------------------------

async function fetchRepair(id: string): Promise<RepairDetailResponse> {
  const response = await fetch(`/api/repairs/${id}`)
  if (!response.ok) {
    throw new Error('Failed to fetch repair')
  }
  return response.json()
}

/** Search parts catalog by name (case-insensitive partial match) */
async function searchParts(query: string): Promise<PartCatalogItem[]> {
  const response = await fetch(`/api/parts?search=${encodeURIComponent(query)}`)
  if (!response.ok) return []
  const data = await response.json()
  return data.parts ?? []
}

/** Fetch all active labor services */
async function fetchLaborServices(): Promise<LaborServiceOption[]> {
  const response = await fetch('/api/repairs/labor-services')
  if (!response.ok) return []
  const data = await response.json()
  return data.laborServices ?? []
}

// ---------------------------------------------------------------------------
// Helpers — format values for display
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  const d = new Date(epochMs)
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
}

function formatTime(epochMs: number | null): string {
  if (!epochMs) return '—'
  const d = new Date(epochMs)
  return d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
}

function formatCurrency(cents: number): string {
  return `${(cents / 100).toFixed(2)} EUR`
}

function formatDuration(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000)
  const hours = Math.floor(totalSeconds / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60

  if (hours > 0) {
    return `${hours}h ${minutes}m`
  }
  if (minutes > 0) {
    return `${minutes}m ${seconds}s`
  }
  return `${seconds}s`
}

function formatElapsed(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000)
  const hours = Math.floor(totalSeconds / 3600)
  const minutes = Math.floor((totalSeconds % 3600) / 60)
  const seconds = totalSeconds % 60

  if (hours > 0) {
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
  }
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
}

function getCustomerName(customer?: CustomerInfo): string {
  if (!customer) return '—'
  const parts = [customer.firstName, customer.lastName].filter(Boolean)
  return parts.join(' ') || customer.companyName || '—'
}

/** Look up worker display name and role from the workers list */
function getWorkerDisplay(
  workerId: string | null,
  workersList: WorkerOption[]
): { name: string; role: string } {
  if (!workerId) return { name: 'Unassigned', role: '' }
  const worker = workersList.find((w) => w.id === workerId)
  if (!worker) return { name: workerId.slice(0, 8), role: '' }
  return { name: worker.name, role: worker.role }
}

// ---------------------------------------------------------------------------
// Collapsible Section Component
// ---------------------------------------------------------------------------

function CollapsibleSection({
  title,
  icon: Icon,
  children,
  defaultOpen = true,
}: {
  title: string
  icon: React.ElementType
  children: React.ReactNode
  defaultOpen?: boolean
}) {
  const [isOpen, setIsOpen] = useState(defaultOpen)

  return (
    <div className="border rounded-lg overflow-hidden">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center justify-between px-4 py-3 bg-muted/30 hover:bg-muted/50 transition-colors"
      >
        <div className="flex items-center gap-2 text-sm font-semibold uppercase tracking-wider text-muted-foreground">
          <Icon size={16} />
          {title}
        </div>
        {isOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
      </button>
      {isOpen && <div className="p-4">{children}</div>}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Main Component — Repair Detail Page
// ---------------------------------------------------------------------------

export function RepairDetailPage() {
  const { id } = useParams<{ id: string }>()!
  const navigate = useNavigate()

  const [repair, setRepair] = useState<RepairHeader | null>(null)
  const [customer, setCustomer] = useState<CustomerInfo | undefined>()
  const [bicycle, setBicycle] = useState<BicycleInfo | null>(null)
  const [lineItems, setLineItems] = useState<LineItem[]>([])
  const [workLogs, setWorkLogs] = useState<WorkLog[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Timer state
  const [activeTimer, setActiveTimer] = useState<WorkLog | null>(null)
  const [elapsedMs, setElapsedMs] = useState(0)
  const [isRunning, setIsRunning] = useState(false)
  const [timerError, setTimerError] = useState<string | null>(null)

  // Worker assignment state
  const [workers, setWorkers] = useState<WorkerOption[]>([])
  const [assigning, setAssigning] = useState(false)

  // Notes editing state — tracks which note type is being edited (or null for view mode)
  const [editingNote, setEditingNote] = useState<'customer' | 'internal' | null>(null)

  // ---------------------------------------------------------------------------
  // Line Item Management State
  // ---------------------------------------------------------------------------

  /** Which tab is active in the add line item section */
  const [addLineItemTab, setAddLineItemTab] = useState<'parts' | 'labor'>('parts')

  /** Parts search state (debounced) — mirrors POS pattern */
  const [partsSearchTerm, setPartsSearchTerm] = useState('')
  const [partsResults, setPartsResults] = useState<PartCatalogItem[]>([])
  const [isSearchingParts, setIsSearchingParts] = useState(false)
  const [highlightedPartIndex, setHighlightedPartIndex] = useState(-1)
  const [isPartsDropdownOpen, setIsPartsDropdownOpen] = useState(false)
  const partsSearchRef = useRef<HTMLInputElement>(null)

  /** Barcode scan state — mirrors POS pattern */
  const [barcodeInput, setBarcodeInput] = useState('')
  const [barcodeError, setBarcodeError] = useState<string | null>(null)

  /** Labor services state */
  const [laborServices, setLaborServices] = useState<LaborServiceOption[]>([])
  const [showLaborDropdown, setShowLaborDropdown] = useState(false)

  /** Edit mode for line items — tracks which item is being edited (or null) */
  const [editingItemId, setEditingItemId] = useState<string | null>(null)
  const [editQuantity, setEditQuantity] = useState<number>(1)
  const [editUnitPriceNet, setEditUnitPriceNet] = useState<number>(0)

  /** Loading state for line item operations */
  const [lineItemLoading, setLineItemLoading] = useState(false)
  const [savingNote, setSavingNote] = useState(false)
  const [tempCustomerNotes, setTempCustomerNotes] = useState<string>('')
  const [tempInternalNotes, setTempInternalNotes] = useState<string>('')

  // Date editing state — tracks which date field is being edited (or null for view mode)
  const [editingDate, setEditingDate] = useState<'planned' | 'pickup' | null>(null)
  const [tempPlannedDate, setTempPlannedDate] = useState<string>('')
  const [tempPickupDate, setTempPickupDate] = useState<string>('')

  // ===========================================================================
  // Special Item Form State
  // ===========================================================================

  /** Whether the special item form is expanded */
  const [specialFormOpen, setSpecialFormOpen] = useState(false)

  /** Special item name input */
  const [specialName, setSpecialName] = useState('')

  /** Special item price in cents (integer) */
  const [specialPriceCents, setSpecialPriceCents] = useState('')

  /** VAT rate basis points: 2100=standard(21%), 600=reduced(6%), 0=zero(0%) */
  const [specialVatRateBps, setSpecialVatRateBps] = useState(2100)

  /** Special item quantity (default 1) */
  const [specialQuantity, setSpecialQuantity] = useState('1')

  /** Inline validation errors for the special form */
  const [specialErrors, setSpecialErrors] = useState<{ name?: string; price?: string }>({})

  /** Submission loading state */
  const [specialSubmitting, setSpecialSubmitting] = useState(false)

  // Load repair detail
  const loadRepair = useCallback(async () => {
    if (!id) return
    setLoading(true)
    setError(null)
    try {
      const data = await fetchRepair(id)
      setRepair(data.repair)
      setCustomer(data.customer)
      setBicycle(data.bicycle ?? null)
      setLineItems(data.lineItems)
      setWorkLogs(data.workLogs)

      // Find active timer (endedAt is null)
      const active = data.workLogs.find((wl) => wl.endedAt === null && wl.startedAt !== null)
      setActiveTimer(active ?? null)
      setIsRunning(!!active)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load repair')
    } finally {
      setLoading(false)
    }
  }, [id])

  // Load workers list for assignment dropdown
  useEffect(() => {
    async function loadWorkers() {
      try {
        const response = await fetch('/api/users')
        if (!response.ok) return
        const data = await response.json()
        setWorkers(data)
      } catch {
        // Silently fail — dropdown still works without workers list
      }
    }
    loadWorkers()
  }, [])

  // Load labor services for the labor tab
  useEffect(() => {
    async function loadLaborServices() {
      try {
        const services = await fetchLaborServices()
        setLaborServices(services)
      } catch {
        // Silently fail — labor tab still works without services list
      }
    }
    loadLaborServices()
  }, [])

  // Debounced parts search — mirrors POS pattern (250ms delay)
  useEffect(() => {
    if (!partsSearchTerm.trim()) {
      setPartsResults([])
      setIsPartsDropdownOpen(false)
      return
    }

    const timer = setTimeout(async () => {
      setIsSearchingParts(true)
      try {
        const results = await searchParts(partsSearchTerm)
        setPartsResults(results)
        setIsPartsDropdownOpen(results.length > 0)
      } catch {
        // Silently fail — show empty results
        setPartsResults([])
        setIsPartsDropdownOpen(false)
      } finally {
        setIsSearchingParts(false)
      }
    }, 250)

    return () => clearTimeout(timer)
  }, [partsSearchTerm])

  useEffect(() => {
    loadRepair()
  }, [loadRepair])

  // Update elapsed time for active timer (poll every second)
  useEffect(() => {
    if (!isRunning || !activeTimer?.startedAt) return

    const interval = setInterval(() => {
      setElapsedMs(Date.now() - activeTimer.startedAt!)
    }, 1000)

    return () => clearInterval(interval)
  }, [isRunning, activeTimer])

  // Handle start timer
  const handleStartTimer = async () => {
    if (!id || !repair?.assignedTo) return
    setTimerError(null)
    try {
      const result = await fetch(`/api/repairs/${id}/timer/start`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: repair.assignedTo }),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to start timer' }))
        throw new Error(error.error || 'Failed to start work timer')
      }

      const workLog = await result.json() as WorkLog
      setActiveTimer(workLog)
      setIsRunning(true)
      setElapsedMs(0)
    } catch (err) {
      setTimerError(err instanceof Error ? err.message : 'Failed to start timer')
    }
  }

  // Handle stop timer
  const handleStopTimer = async () => {
    if (!activeTimer?.id || !id) return
    setTimerError(null)
    try {
      const result = await fetch(`/api/repairs/${id}/timer/stop`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workLogId: activeTimer.id }),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to stop timer' }))
        throw new Error(error.error || 'Failed to stop work timer')
      }

      const updatedWorkLog = await result.json() as WorkLog
      // Update the work logs list with the stopped entry
      setWorkLogs((prev) => prev.map((wl) => wl.id === activeTimer.id ? updatedWorkLog : wl))
      setActiveTimer(null)
      setIsRunning(false)
      setElapsedMs(0)

      // Reload to refresh the full detail view
      loadRepair()
    } catch (err) {
      setTimerError(err instanceof Error ? err.message : 'Failed to stop timer')
    }
  }

  // Handle worker assignment change
  const handleAssignWorker = async (workerId: string | null) => {
    if (!id || !repair) return
    setAssigning(true)
    try {
      const result = await fetch(`/api/repairs/${id}/assign`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ assignedTo: workerId }),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to assign worker' }))
        throw new Error(error.error || 'Failed to assign worker')
      }

      // Update local state with the new assignment
      setRepair((prev) => prev ? { ...prev, assignedTo: workerId } : null)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to assign worker'
      toast.error(message)
    } finally {
      setAssigning(false)
    }
  }

// ===========================================================================
  // Line Item Management Handlers
  // ===========================================================================

  /** Add a part to the repair line items */
  const handleAddPart = useCallback(async (part: PartCatalogItem) => {
    if (!id || !repair || repair.status === 'completed') return
    setLineItemLoading(true)
    try {
      // Use the part's price as unitPriceNet, standard VAT rate ID
      // We need a default VAT rate — use the first available or 21% (standard)
      const result = await fetch(`/api/repairs/${id}/items`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineType: 'part' as const,
          partId: part.id,
          description: part.name,
          quantity: 1,
          unitPriceNet: part.priceNet,
          vatRateId: 'vat-standard', // standard VAT rate
        }),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to add line item' }))
        throw new Error(error.error || 'Failed to add line item')
      }

      // Reload the repair to get updated line items
      await loadRepair()

      // Reset search state for rapid next-item entry
      setPartsSearchTerm('')
      setPartsResults([])
      setIsPartsDropdownOpen(false)
      setHighlightedPartIndex(-1)
      partsSearchRef.current?.focus()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to add line item'
      toast.error(message)
    } finally {
      setLineItemLoading(false)
    }
  }, [id, repair, loadRepair])

  /** Add a labor service to the repair line items */
  const handleAddLabor = useCallback(async (service: LaborServiceOption) => {
    if (!id || !repair || repair.status === 'completed') return
    setLineItemLoading(true)
    try {
      const result = await fetch(`/api/repairs/${id}/items`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineType: 'labor' as const,
          laborServiceId: service.id,
          description: service.name,
          quantity: 1,
          unitPriceNet: service.defaultRate,
          vatRateId: 'vat-standard', // standard VAT rate
        }),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to add line item' }))
        throw new Error(error.error || 'Failed to add line item')
      }

      // Reload the repair to get updated line items
      await loadRepair()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to add line item'
      toast.error(message)
    } finally {
      setLineItemLoading(false)
    }
  }, [id, repair, loadRepair])

  /** Barcode scan — adds part to line items on Enter or blur (mirrors POS pattern) */
  const handleBarcodeSubmit = useCallback(async () => {
    if (!barcodeInput.trim() || !id || !repair || repair.status === 'completed') return

    setLineItemLoading(true)
    try {
      const response = await fetch(`/api/parts?search=${encodeURIComponent(barcodeInput.trim())}`)
      if (response.ok) {
        const data = (await response.json()) as { parts: PartCatalogItem[] }
        // Barcode scanners send exact matches — take the first result
        if (data.parts.length > 0) {
          await handleAddPart(data.parts[0])
          setBarcodeInput('')
          setBarcodeError(null)
          return
        }
        // No part found with this barcode
        setBarcodeError('No part found with this barcode')
      }
    } catch {
      // Silently fail — don't show error on network issues
    } finally {
      setLineItemLoading(false)
      if (!barcodeError) {
        setBarcodeInput('')
      }
    }
  }, [barcodeInput, handleAddPart])

  /** Start editing a line item */
  const handleStartEditLineItem = (item: LineItem) => {
    if (!repair || repair.status === 'completed') return
    setEditingItemId(item.id)
    setEditQuantity(item.quantity)
    setEditUnitPriceNet(item.unitPriceNet)
  }

  /** Cancel editing a line item */
  const handleCancelEditLineItem = () => {
    setEditingItemId(null)
  }

  /** Save edited line item */
  const handleSaveLineItem = useCallback(async (itemId: string) => {
    if (!id || !repair || repair.status === 'completed') return
    setLineItemLoading(true)
    try {
      const result = await fetch(`/api/repairs/${id}/items/${itemId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          quantity: editQuantity,
          unitPriceNet: editUnitPriceNet,
        }),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to update line item' }))
        throw new Error(error.error || 'Failed to update line item')
      }

      // Reload the repair to get updated totals
      await loadRepair()
      setEditingItemId(null)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update line item'
      toast.error(message)
    } finally {
      setLineItemLoading(false)
    }
  }, [id, repair, editQuantity, editUnitPriceNet, loadRepair])

  /** Delete a line item */
  const handleDeleteLineItem = useCallback(async (itemId: string) => {
    if (!id || !repair || repair.status === 'completed') return
    setLineItemLoading(true)
    try {
      const result = await fetch(`/api/repairs/${id}/items/${itemId}`, {
        method: 'DELETE',
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to delete line item' }))
        throw new Error(error.error || 'Failed to delete line item')
      }

      // Reload the repair to get updated totals
      await loadRepair()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to delete line item'
      toast.error(message)
    } finally {
      setLineItemLoading(false)
    }
  }, [id, repair, loadRepair])

  /** Keyboard navigation for parts search dropdown */
  const handlePartsSearchKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isPartsDropdownOpen || partsResults.length === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedPartIndex(prev => Math.min(prev + 1, partsResults.length - 1))
        break
      case 'ArrowUp':
        e.preventDefault()
        setHighlightedPartIndex(prev => Math.max(prev - 1, 0))
        break
      case 'Enter':
        e.preventDefault()
        if (highlightedPartIndex >= 0 && highlightedPartIndex < partsResults.length) {
          handleAddPart(partsResults[highlightedPartIndex])
        } else if (partsResults.length === 1) {
          // Single result — auto-select on Enter
          handleAddPart(partsResults[0])
        }
        break
      case 'Escape':
        e.preventDefault()
        setIsPartsDropdownOpen(false)
        setHighlightedPartIndex(-1)
        break
    }
  }, [isPartsDropdownOpen, partsResults, highlightedPartIndex, handleAddPart])

  // ===========================================================================
  // Special Item Handlers
  // ===========================================================================

  /** Validate the special item form — returns true if valid */
  const validateSpecialForm = useCallback((): boolean => {
    const newErrors: { name?: string; price?: string } = {}

    if (!specialName.trim()) {
      newErrors.name = 'Name is required'
    }

    const parsedPrice = parseInt(specialPriceCents, 10)
    if (!specialPriceCents || isNaN(parsedPrice)) {
      newErrors.price = 'Price is required (in cents)'
    } else if (parsedPrice <= 0) {
      newErrors.price = 'Price must be greater than 0'
    }

    setSpecialErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }, [specialName, specialPriceCents])

  /** Create a special item: POST /parts/special → POST /repairs/:id/items */
  const handleCreateSpecialItem = useCallback(async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateSpecialForm()) return
    if (!id || !repair || repair.status === 'completed') return

    setSpecialSubmitting(true)
    setSpecialErrors({})

    try {
      const parsedPrice = parseInt(specialPriceCents, 10)
      const quantity = Math.max(1, parseInt(specialQuantity, 10) || 1)

      // Step 1: Create the part in inventory via POST /parts/special
      const specialPayload = {
        name: specialName.trim(),
        priceNet: parsedPrice,
        vatRateBasisPoints: specialVatRateBps,
      }

      const specialResponse = await fetch('/api/parts/special', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(specialPayload),
      })

      if (!specialResponse.ok) {
        const errorData = await specialResponse.json().catch(() => null)
        throw new Error(errorData?.error || `Server error: ${specialResponse.status}`)
      }

      // Step 2: Add the newly created part as a repair line item via POST /repairs/:id/items
      const vatRateMap: Record<number, string> = {
        2100: 'vat-standard',
        600: 'vat-reduced',
        0: 'vat-zero',
      }

      const itemPayload = {
        lineType: 'part' as const,
        partId: (await specialResponse.json()).id,
        description: specialName.trim(),
        quantity,
        unitPriceNet: parsedPrice,
        vatRateId: vatRateMap[specialVatRateBps] ?? 'vat-standard',
      }

      const itemResponse = await fetch(`/api/repairs/${id}/items`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(itemPayload),
      })

      if (!itemResponse.ok) {
        const errorData = await itemResponse.json().catch(() => null)
        throw new Error(errorData?.error || `Server error: ${itemResponse.status}`)
      }

      // Reload repair to get updated line items
      await loadRepair()

      // Reset form state after successful creation
      setSpecialName('')
      setSpecialPriceCents('')
      setSpecialVatRateBps(2100)
      setSpecialQuantity('1')
      setSpecialErrors({})

      toast.success('Special item added successfully')
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create special item'
      setSpecialErrors({ price: message })
      toast.error(message)
    } finally {
      setSpecialSubmitting(false)
    }
  }, [id, repair, loadRepair, specialName, specialPriceCents, specialVatRateBps, specialQuantity, validateSpecialForm])

  /** Reset form state when closing */
  useEffect(() => {
    if (!specialFormOpen) {
      setSpecialName('')
      setSpecialPriceCents('')
      setSpecialVatRateBps(2100)
      setSpecialQuantity('1')
      setSpecialErrors({})
    }
  }, [specialFormOpen])

  // ===========================================================================
  // Notes editing handlers
  // ===========================================================================

  /** Handle notes editing — start edit mode for a note type */
  const handleStartEditNotes = (noteType: 'customer' | 'internal') => {
    if (!repair) return
    setEditingNote(noteType)
    if (noteType === 'customer') {
      setTempCustomerNotes(repair.customerNotes ?? '')
    } else {
      setTempInternalNotes(repair.internalNotes ?? '')
    }
  }

  // Handle cancel — discard changes and return to view mode
  const handleCancelEditNotes = () => {
    setEditingNote(null)
  }

  // Handle save notes
  const handleSaveNotes = async (noteType: 'customer' | 'internal') => {
    if (!id || !repair) return
    setSavingNote(true)
    try {
      const payload: { customerNotes?: string | null; internalNotes?: string | null } = {}
      if (noteType === 'customer') {
        payload.customerNotes = tempCustomerNotes || null
      } else {
        payload.internalNotes = tempInternalNotes || null
      }

      const result = await fetch(`/api/repairs/${id}/notes`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to update notes' }))
        throw new Error(error.error || 'Failed to update notes')
      }

      // Update local state with the saved value
      setRepair((prev) => {
        if (!prev) return prev
        const updated = { ...prev }
        if (noteType === 'customer') {
          updated.customerNotes = tempCustomerNotes || null
        } else {
          updated.internalNotes = tempInternalNotes || null
        }
        return updated
      })

      toast.success('Notes saved successfully')
      setEditingNote(null)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save notes'
      toast.error(message)
    } finally {
      setSavingNote(false)
    }
  }

  // ===========================================================================
  // Date editing handlers
  // ===========================================================================

  /** Convert epoch ms to YYYY-MM-DD for <input type="date"> */
  function epochToInputDate(epochMs: number | null): string {
    if (!epochMs) return ''
    const d = new Date(epochMs)
    return d.toISOString().split('T')[0]
  }

  /** Convert YYYY-MM-DD from <input type="date"> to epoch ms */
  function inputDateToEpoch(dateStr: string): number | null {
    if (!dateStr) return null
    const d = new Date(dateStr + 'T00:00:00')
    return isNaN(d.getTime()) ? null : d.getTime()
  }

  /** Handle date editing — start edit mode for a date field */
  const handleStartEditDate = (dateType: 'planned' | 'pickup') => {
    if (!repair) return
    setEditingDate(dateType)
    if (dateType === 'planned') {
      setTempPlannedDate(epochToInputDate(repair.plannedDate))
    } else {
      setTempPickupDate(epochToInputDate(repair.pickupDate))
    }
  }

  /** Handle cancel — discard changes and return to view mode */
  const handleCancelEditDate = () => {
    setEditingDate(null)
  }

  /** Handle save dates */
  const handleSaveDates = async (dateType: 'planned' | 'pickup') => {
    if (!id || !repair) return
    setSavingNote(true)
    try {
      const payload: { plannedDate?: number | null; pickupDate?: number | null } = {}
      if (dateType === 'planned') {
        payload.plannedDate = inputDateToEpoch(tempPlannedDate)
      } else {
        payload.pickupDate = inputDateToEpoch(tempPickupDate)
      }

      const result = await fetch(`/api/repairs/${id}/notes`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!result.ok) {
        const error = await result.json().catch(() => ({ error: 'Failed to update dates' }))
        throw new Error(error.error || 'Failed to update dates')
      }

      // Update local state with the saved value
      setRepair((prev) => {
        if (!prev) return prev
        const updated = { ...prev }
        if (dateType === 'planned') {
          updated.plannedDate = inputDateToEpoch(tempPlannedDate)
        } else {
          updated.pickupDate = inputDateToEpoch(tempPickupDate)
        }
        return updated
      })

      toast.success('Dates saved successfully')
      setEditingDate(null)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save dates'
      toast.error(message)
    } finally {
      setSavingNote(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    )
  }

  if (error || !repair) {
    return (
      <div className="p-6">
        <button
          onClick={() => navigate('/repairs')}
          className="flex items-center gap-2 text-muted-foreground hover:text-foreground mb-4"
        >
          <ArrowLeft size={16} /> Back to repairs
        </button>
        <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error || 'Repair not found'}
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 max-w-4xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <button
          onClick={() => navigate('/repairs')}
          className="flex items-center gap-2 text-muted-foreground hover:text-foreground"
        >
          <ArrowLeft size={16} /> Back to repairs
        </button>
        <span className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium ${STATUS_COLORS[repair.status]}`}>
          {repair.status.replace('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase())}
        </span>
      </div>

      {/* Repair Header Info */}
      <div className="mb-6 p-4 border rounded-lg bg-card">
        <h1 className="text-xl font-bold mb-2">Repair #{repair.id.slice(0, 8)}</h1>

        {/* Worker Assignment Dropdown — in header section */}
        <div className="mb-4">
          <label className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
            <User size={12} className="inline mr-1" />
            Assigned Worker
          </label>
          <select
            value={repair.assignedTo ?? ''}
            onChange={(e) => handleAssignWorker(e.target.value || null)}
            disabled={assigning || repair.status === 'completed'}
            className="w-full sm:w-64 h-9 px-3 text-sm border rounded-md bg-background focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <option value="">Unassigned</option>
            {workers.map((worker) => (
              <option key={worker.id} value={worker.id}>
                {worker.name} ({worker.role})
              </option>
            ))}
          </select>
        </div>

        <div className="grid grid-cols-2 gap-4 text-sm">
          {customer && (
            <>
              <div>
                <span className="text-muted-foreground">Customer: </span>
                <span>{getCustomerName(customer)}</span>
              </div>
              {customer.phone && (
                <div>
                  <span className="text-muted-foreground">Phone: </span>
                  <span>{customer.phone}</span>
                </div>
              )}
            </>
          )}
          {bicycle && (
            <>
              <div>
                <span className="text-muted-foreground">Bicycle: </span>
                <span>{bicycle.brand} {bicycle.model}{bicycle.color ? ` (${bicycle.color})` : ''}</span>
              </div>
              <div>
                <span className="text-muted-foreground">Assigned: </span>
                <span>{getWorkerDisplay(repair.assignedTo, workers).name}</span>
                {getWorkerDisplay(repair.assignedTo, workers).role && (
                  <span className={`ml-2 inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
                    getWorkerDisplay(repair.assignedTo, workers).role === 'mechanic'
                      ? 'bg-blue-100 text-blue-800'
                      : 'bg-purple-100 text-purple-800'
                  }`}>
                    {getWorkerDisplay(repair.assignedTo, workers).role}
                  </span>
                )}
              </div>
            </>
          )}
        </div>
      </div>

      {/* Timer Section — always visible at top */}
      <CollapsibleSection title="Work Timer" icon={Clock}>
        {timerError && (
          <div className="mb-3 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-700">
            {timerError}
          </div>
        )}

        {/* Active Timer Display */}
        {isRunning && activeTimer ? (
          <div className="flex items-center justify-between p-4 bg-green-50 border border-green-200 rounded-lg">
            <div className="flex items-center gap-3">
              <div className="w-3 h-3 rounded-full bg-green-500 animate-pulse"></div>
              <div>
                <div className="text-sm font-medium text-green-800">Timer Running</div>
                <div className="text-xs text-green-600">Started at {activeTimer.startedAt ? formatTime(activeTimer.startedAt) : '—'}</div>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <span className="text-2xl font-mono font-bold text-green-800 tabular-nums">
                {formatElapsed(elapsedMs)}
              </span>
              <button
                onClick={handleStopTimer}
                className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg flex items-center gap-2 transition-colors"
              >
                <Square size={16} /> Stop Timer
              </button>
            </div>
          </div>
        ) : (
          /* Start Timer Button */
          <div className="flex items-center justify-between p-4 bg-muted/30 rounded-lg">
            <div>
              <div className="text-sm font-medium text-muted-foreground">No active timer</div>
              <div className="text-xs text-muted-foreground">
                {repair.assignedTo ? `Timer will be logged for ${getWorkerDisplay(repair.assignedTo, workers).name}` : 'Assign a worker first'}
              </div>
            </div>
            <button
              onClick={handleStartTimer}
              disabled={!repair.assignedTo || repair.status === 'completed'}
              className="px-4 py-2 bg-green-600 hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-lg flex items-center gap-2 transition-colors"
            >
              <Play size={16} /> Start Timer
            </button>
          </div>
        )}

        {/* Cumulative Time */}
        {workLogs.length > 0 && (
          <div className="mt-3 text-xs text-muted-foreground">
            Total logged time:{' '}
            {formatDuration(
              workLogs.reduce((sum, wl) => sum + (wl.durationMs || 0), 0)
            )}{' '}
            ({workLogs.length} session{workLogs.length !== 1 ? 's' : ''})
          </div>
        )}

        {/* Work Log History */}
        {workLogs.length > 0 && (
          <div className="mt-3 border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-muted/50">
                <tr>
