                  <th className="px-3 py-2 text-left font-semibold text-muted-foreground">Started</th>
                  <th className="px-3 py-2 text-left font-semibold text-muted-foreground">Ended</th>
                  <th className="px-3 py-2 text-right font-semibold text-muted-foreground">Duration</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {workLogs.map((wl, idx) => (
                  <tr key={wl.id} className={wl.endedAt === null ? 'bg-green-50/50' : ''}>
                    <td className="px-3 py-2 text-muted-foreground">{idx + 1}</td>
                    <td className="px-3 py-2">
                      {wl.startedAt ? formatTime(wl.startedAt) : '—'}
                      {wl.endedAt === null && (
                        <span className="ml-1 inline-block w-2 h-2 rounded-full bg-green-500"></span>
                      )}
                    </td>
                    <td className="px-3 py-2">
                      {wl.endedAt ? formatTime(wl.endedAt) : '—'}
                    </td>
                    <td className="px-3 py-2 text-right font-mono tabular-nums">
                      {wl.durationMs ? formatDuration(wl.durationMs) : 'Running...'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </CollapsibleSection>

      {/* ==========================================================================
          Line Items Section
          ========================================================================== */}
      <CollapsibleSection title="Line Items" icon={FileText}>
        {/* Add Line Item Section — only shown when repair is not completed */}
        {repair.status !== 'completed' && (
