/**
 * Users Routes — Worker lookup for repair assignment UI.
 */

import { Hono } from 'hono'
import { getActiveWorkers } from '../services/users.service.js'

const usersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /users — List active workers for dropdown selectors
//
// Returns compact worker data (id, name, role) sorted by name.
// Only returns active workers (isActive=true).
// ---------------------------------------------------------------------------

usersRoutes.get('/', async () => {
  const workers = await getActiveWorkers()
  return new Response(JSON.stringify(workers), {
    headers: { 'Content-Type': 'application/json' },
  })
})

export default usersRoutes

import { Hono } from 'hono'
import {
  createRepairIntake,
  getRepairsList,
  getRepairById,
  transitionRepairStatus,
  updateRepairNotes,
  getCustomerWithBicycles,
  createRepairLineItem,
  updateRepairLineItem,
  deleteRepairLineItem,
  listLaborServices,
  getLaborServiceById,
  createLaborService,
  updateLaborService,
  deactivateLaborService,
  assignWorkerToRepair,
  startWorkTimer,
  stopWorkTimer,
  completeRepairPayment,
  type RepairDetail,
  type RepairStatus,
} from '../services/repair.service.js'

const repairsRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /repairs — Paginated list of repairs with filtering and sorting
//
// Query params:
//   status       - Filter by status (intake, in_progress, on_hold, verified, ready, completed, cancelled)
//   assignedTo   - Filter by worker ID or 'unassigned' for NULL assignments
//  pickupDate    - Filter by pickup date: 'today' or 'this_week'
//   page         - Page number (1-indexed, default 1)
//   pageSize     - Items per page (default 20)
//
// Default sort: planned_date DESC (most urgent first), then created_at DESC
// ---------------------------------------------------------------------------

repairsRoutes.get('/', async (c) => {
  const status = c.req.query('status') as string | undefined
  const assignedToRaw = c.req.query('assignedTo') as string | undefined
  const pickupDateFilter = c.req.query('pickupDate') as 'today' | 'this_week' | undefined
  const page = parseInt(c.req.query('page') || '1', 10)
  const pageSize = Math.min(parseInt(c.req.query('pageSize') || '20', 10), 100) // cap at 100

  // Build filters
  const filters: Parameters<typeof getRepairsList>[0] = {}

  if (status && ['intake', 'in_progress', 'on_hold', 'verified', 'ready', 'completed', 'cancelled'].includes(status)) {
    filters.status = status as RepairStatus
  }

  if (assignedToRaw === 'unassigned') {
    filters.assignedTo = null
  } else if (assignedToRaw) {
    filters.assignedTo = assignedToRaw
  }

  if (pickupDateFilter && ['today', 'this_week'].includes(pickupDateFilter)) {
    filters.pickupDateFilter = pickupDateFilter
  }

  const result = await getRepairsList(filters, page, pageSize)
  return c.json(result)
})

// ---------------------------------------------------------------------------
// POST /repairs — Create a new repair via intake flow
//
// Accepts customer (search existing or create inline), bicycle (select from
// customer's bikes or create inline with brand/model/color), and notes.
// Repairs are created with status='intake' and assignedTo=NULL.
// ---------------------------------------------------------------------------

repairsRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const repair = await createRepairIntake(input)
    return c.json(repair, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    // Zod validation error or business logic error
    const message = err instanceof Error ? err.message : 'Validation failed'
    const status = (err as { code?: string; name?: string }).code === 'NOT_FOUND' || (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/customers/:customerId — Get customer with bicycles for intake
// ---------------------------------------------------------------------------

repairsRoutes.get('/customers/:customerId', async (c) => {
  const customerId = c.req.param('customerId')
  const customerWithBicycles = await getCustomerWithBicycles(customerId)

  if (!customerWithBicycles) {
    return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(customerWithBicycles)
})

// ---------------------------------------------------------------------------
// GET /repairs/labor-services — List available labor services catalog
// ---------------------------------------------------------------------------

repairsRoutes.get('/labor-services', async (c) => {
  const billingType = c.req.query('billingType') as 'hourly' | 'fixed' | undefined

  try {
    const services = await listLaborServices(billingType ? { billingType } : {})
    return c.json({ laborServices: services, total: services.length })
  } catch (err) {
    console.error('[GET /labor-services] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to fetch labor services', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/labor-services/:id — Get single labor service detail
// ---------------------------------------------------------------------------

repairsRoutes.get('/labor-services/:id', async (c) => {
  const id = c.req.param('id')
  try {
    const service = await getLaborServiceById(id)
    if (!service) {
      return c.json({ error: 'Labor service not found', code: 'NOT_FOUND' }, 404)
    }
    return c.json(service)
  } catch (err) {
    console.error('[GET /labor-services/:id] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to fetch labor service', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/labor-services — Create a new labor service
// ---------------------------------------------------------------------------

repairsRoutes.post('/labor-services', async (c) => {
  const input = await c.req.json()

  try {
    if (!input?.name || !input.name.trim()) {
      return c.json({ error: 'Name is required', code: 'VALIDATION_ERROR' }, 400)
    }
    if (typeof input.defaultRate !== 'number' || input.defaultRate <= 0) {
      return c.json({ error: 'defaultRate must be a positive number', code: 'VALIDATION_ERROR' }, 400)
    }

    const service = await createLaborService(input)
    return c.json(service, 201)
  } catch (err) {
    console.error('[POST /labor-services] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to create labor service', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/labor-services/:id — Update a labor service
// ---------------------------------------------------------------------------

repairsRoutes.patch('/labor-services/:id', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const service = await updateLaborService(id, input)
    return c.json(service)
  } catch (err) {
    if ((err as { name?: string }).name === 'LaborServiceNotFoundError') {
      return c.json({ error: 'Labor service not found', code: 'NOT_FOUND' }, 404)
    }
    console.error('[PATCH /labor-services/:id] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to update labor service', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/labor-services/:id/deactivate — Deactivate a labor service
// ---------------------------------------------------------------------------

